# create a calculator using python without use input
a=10
b=5
print(a+b)
print(a-b)
print(a*b)
print(a/b) #gives decimal values 
print(a//b) #use floor division funtion and rounds up the value
print(a**b) #exponential operator to calculate power
print(a%b) # modulus operator to get reminder

# create a calculator using python by taking input from user
a=int(input("enter the 1st num:"))
b=int(input("enter the 2nd num:"))
print(a+b)
print(a-b)
print(a*b)
print(a/b) #gives decimal values 
print(a//b) #use floor division funtion and rounds up the value
print(a**b) #exponential operator to calculate power
print(a%b) 
